/* Field-level explanation for the Spare Parts inventory flow. */
(function(){
  function stockFlowGuide(){return `<section class="partsStockGuide panel"><div class="panelhead"><h2>${icon('box')} How Spare Parts Stock Updates</h2></div><div class="panelbody"><p class="partsStockGuideIntro">Use this guide to understand how each stock field is updated. Main Stock is the quantity available for Job Cards and counter sales.</p><div class="partsStockFormula"><strong>Main Stock</strong><span>= Opening Stock + Purchase into Main + Transfer In − Sales / Used</span></div><div class="partsStockGuideGrid"><article><h3>Opening Stock</h3><p>Starting quantity entered once in the Spare Parts Master. It adds directly to Main Stock.</p></article><article><h3>Purchase</h3><p>A saved Purchase Entry adds quantity to the selected destination. Godown receipts do not increase Main Stock until transferred.</p></article><article><h3>Transfer In</h3><p>Godown Stock → Transfer to Main Stock moves the same quantity out of Godown and into Main Stock.</p></article><article><h3>Sales / Used</h3><p>A saved Job Card or Spare Parts Sale reduces Main Stock only. Transfer stock from Godown first if needed.</p></article><article><h3>Main Stock</h3><p>Live calculated balance available for new job cards and sales. It is not typed manually.</p></article><article><h3>Min Stock Alert</h3><p>When Main Stock is equal to or below this quantity, the part is marked Low Stock. At zero, it is Out of Stock.</p></article></div><p class="partsStockGuideNote"><strong>Purchase price:</strong> Each receipt keeps its own bill or movement cost. The master purchase-price reference refreshes only when combined Main Stock and Godown stock is zero before a new receipt. Selling price is managed in Spare Parts.</p><p class="partsStockGuideNote"><strong>History:</strong> Use the Spare Parts Movement History Report for part-wise, date-wise opening stock, purchases, transfers and issues.</p></div></section>`}
  const renderBeforePartsStockGuide=render;
  render=function(){const result=renderBeforePartsStockGuide();if(page==='parts'&&!$('#partsStockFlowGuide')){$('#content').insertAdjacentHTML('beforeend',stockFlowGuide().replace('class="partsStockGuide panel"','id="partsStockFlowGuide" class="partsStockGuide panel"'))}return result};
  if(page==='parts')render();
})();
